const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("gsl_rpc_response_topic", msg.rpcResponseTopic);
flow.set("gsl_write_result", msg.writeResult || null);

// Clear all parts
flow.set("gsl_part_gen_timing", null);
flow.set("gsl_part_gen_charge", null);
flow.set("gsl_part_enables", null);
flow.set("gsl_part_smartload1", null);
flow.set("gsl_part_reg278", null);
flow.set("gsl_part_reg290", null);
flow.set("gsl_part_reg292", null);

return msg;

msg.readGroup = "gen_timing";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 221,
    quantity: 2
};
return msg;

msg.readGroup = "gen_charge";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 224,
    quantity: 2
};
return msg;

msg.readGroup = "enables";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 229,
    quantity: 2
};
return msg;

msg.readGroup = "smartload1";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 233,
    quantity: 7
};
return msg;

msg.readGroup = "reg278";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 278,
    quantity: 1
};
return msg;

msg.readGroup = "reg290";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 290,
    quantity: 1
};
return msg;

msg.readGroup = "reg292";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 292,
    quantity: 1
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

const group = msg.readGroup;

if (group === "gen_timing") {
    flow.set("gsl_part_gen_timing", {
        maxRunTimeHours: Math.round((data[0] || 0) * 0.1 * 10) / 10,
        coolingTimeHours: Math.round((data[1] || 0) * 0.1 * 10) / 10
    });
}
else if (group === "gen_charge") {
    flow.set("gsl_part_gen_charge", {
        startSocPercent: data[0] || 0,
        chargeCurrentA: data[1] || 0
    });
}
else if (group === "enables") {
    flow.set("gsl_part_enables", {
        generatorChargeEnabled: (data[0] || 0) === 1,
        gridChargeEnabled: (data[1] || 0) === 1
    });
}
else if (group === "smartload1") {
    // 233, 234, 235, 236, 237, 238, 239
    flow.set("gsl_part_smartload1", {
        smartLoadEnabled: data[0] || 0,        // 233
        offSocPercent: data[2] || 0,           // 235
        onSocPercent: data[4] || 0,            // 237
        pvPowerThresholdW: data[6] || 0        // 239
    });
}
else if (group === "reg278") {
    const val = data[0] || 0;
    // Bit2-3: Gen peak shaving (10=disable, 11=enable)
    const genPeakShavingEnabled = ((val >> 2) & 0x03) === 0x03;
    // Bit6-7: On Grid always on (10=disable, 11=enable)
    const onGridAlwaysOn = ((val >> 6) & 0x03) === 0x03;

    flow.set("gsl_part_reg278", {
        rawValue: val,
        genPeakShavingEnabled: genPeakShavingEnabled,
        onGridAlwaysOn: onGridAlwaysOn
    });
}
else if (group === "reg290") {
    flow.set("gsl_part_reg290", {
        limitPowerW: data[0] || 0
    });
}
else if (group === "reg292") {
    flow.set("gsl_part_reg292", {
        openDelayMinutes: data[0] || 0
    });
}
else {
    return null;
}

// Check if all parts received
const genTiming = flow.get("gsl_part_gen_timing");
const genCharge = flow.get("gsl_part_gen_charge");
const enables = flow.get("gsl_part_enables");
const smartload1 = flow.get("gsl_part_smartload1");
const reg278 = flow.get("gsl_part_reg278");
const reg290 = flow.get("gsl_part_reg290");
const reg292 = flow.get("gsl_part_reg292");

if (!genTiming || !genCharge || !enables || !smartload1 || !reg278 || !reg290 || !reg292) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "GeneratorAndSmartLoadConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    // Global enables
    generatorChargeEnabled: enables.generatorChargeEnabled,
    gridChargeEnabled: enables.gridChargeEnabled,

    // Generator settings
    maxRunTimeHours: genTiming.maxRunTimeHours,
    coolingTimeHours: genTiming.coolingTimeHours,
    startSocPercent: genCharge.startSocPercent,
    chargeCurrentA: genCharge.chargeCurrentA,

    // Generator peak shaving
    generatorPeakShaving: {
        enabled: reg278.genPeakShavingEnabled,
        limitPowerW: reg290.limitPowerW
    },

    // Smart Load
    smartLoad: {
        enabled: smartload1.smartLoadEnabled,
        offSocPercent: smartload1.offSocPercent,
        onSocPercent: smartload1.onSocPercent,
        pvPowerThresholdW: smartload1.pvPowerThresholdW,
        openDelayMinutes: reg292.openDelayMinutes,
        onGridAlwaysOn: reg278.onGridAlwaysOn
    }
};

// Store reg278 raw value for write operations
flow.set("gsl_reg278_current", reg278.rawValue);

// Clear parts
flow.set("gsl_part_gen_timing", null);
flow.set("gsl_part_gen_charge", null);
flow.set("gsl_part_enables", null);
flow.set("gsl_part_smartload1", null);
flow.set("gsl_part_reg278", null);
flow.set("gsl_part_reg290", null);
flow.set("gsl_part_reg292", null);

const writeResult = flow.get("gsl_write_result");
const rpcResponseTopic = flow.get("gsl_rpc_response_topic");

flow.set("gsl_write_result", null);
flow.set("gsl_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const genPeak = params.generatorPeakShaving || {};
const smartLoad = params.smartLoad || {};

const writes = [];

// Generator charge settings
if (params.startSocPercent !== undefined) {
    writes.push({ register: 224, value: params.startSocPercent, name: "Gen Start SOC" });
}
if (params.chargeCurrentA !== undefined) {
    writes.push({ register: 225, value: params.chargeCurrentA, name: "Gen Charge Current" });
}

// Enable flags
if (params.generatorChargeEnabled !== undefined) {
    writes.push({ register: 229, value: params.generatorChargeEnabled ? 1 : 0, name: "Gen Charge Enable" });
}
if (params.gridChargeEnabled !== undefined) {
    writes.push({ register: 230, value: params.gridChargeEnabled ? 1 : 0, name: "Grid Charge Enable" });
}

// SmartLoad settings
if (smartLoad.enabled !== undefined) {
    writes.push({ register: 233, value: smartLoad.enabled, name: "SmartLoad Enable" });
}
if (smartLoad.offSocPercent !== undefined) {
    writes.push({ register: 235, value: smartLoad.offSocPercent, name: "SmartLoad OFF SOC" });
}
if (smartLoad.onSocPercent !== undefined) {
    writes.push({ register: 237, value: smartLoad.onSocPercent, name: "SmartLoad ON SOC" });
}
if (smartLoad.pvPowerThresholdW !== undefined) {
    writes.push({ register: 239, value: smartLoad.pvPowerThresholdW, name: "SmartLoad PV Threshold" });
}
if (smartLoad.openDelayMinutes !== undefined) {
    writes.push({ register: 292, value: smartLoad.openDelayMinutes, name: "SmartLoad Open Delay" });
}

// Generator peak shaving power
if (genPeak.limitPowerW !== undefined) {
    writes.push({ register: 290, value: genPeak.limitPowerW, name: "Gen Peak Shaving Power" });
}

// Register 278 bit field - needs special handling
let needReg278Write = false;
let reg278NewValue = flow.get("gsl_reg278_current") || 0;

if (genPeak.enabled !== undefined) {
    needReg278Write = true;
    // Bit2-3: Gen peak shaving (10=disable, 11=enable)
    reg278NewValue = reg278NewValue & ~0x000C; // Clear bits 2-3
    if (genPeak.enabled) {
        reg278NewValue = reg278NewValue | 0x000C; // Set bits 2-3 (11)
    } else {
        reg278NewValue = reg278NewValue | 0x0008; // Set bit 3, clear bit 2 (10)
    }
}

if (smartLoad.onGridAlwaysOn !== undefined) {
    needReg278Write = true;
    // Bit6-7: On Grid always on (10=disable, 11=enable)
    reg278NewValue = reg278NewValue & ~0x00C0; // Clear bits 6-7
    if (smartLoad.onGridAlwaysOn) {
        reg278NewValue = reg278NewValue | 0x00C0; // Set bits 6-7 (11)
    } else {
        reg278NewValue = reg278NewValue | 0x0080; // Set bit 7, clear bit 6 (10)
    }
}

if (needReg278Write) {
    writes.push({ register: 278, value: reg278NewValue, name: "Reg278 Bits" });
}

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("gsl_write_queue", writes);
global.set("gsl_write_index", 0);
global.set("gsl_write_results", []);
global.set("gsl_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("gsl_write_queue") || [];
const index = global.get("gsl_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("gsl_write_queue") || [];
let index = global.get("gsl_write_index") || 0;
const results = global.get("gsl_write_results") || [];

const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("gsl_write_results", results);
}

index++;
global.set("gsl_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [{ doNext: true }, null];
}

const rpcTopic = global.get("gsl_write_rpc_topic");

global.set("gsl_write_queue", null);
global.set("gsl_write_index", null);
global.set("gsl_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
